<?php require_once __DIR__.'/includes/auth.php';require_user();$q=trim($_GET['q']??'');$filter=$_GET['status']??'all';$sql="SELECT r.*,e.title,e.event_date,e.start_time,e.venue,e.image_url,e.status event_status,c.checked_in_at FROM registrations r JOIN events e ON e.id=r.event_id LEFT JOIN checkins c ON c.registration_id=r.id WHERE r.user_id=? AND r.status IN ('valid','cancelled')";$params=[$_SESSION['user_id']];if($q!==''){$sql.=' AND (e.title LIKE ? OR r.registration_code LIKE ?)';$params[]="%$q%";$params[]="%$q%";}if($filter==='upcoming')$sql.=' AND e.event_date>=CURDATE()';elseif($filter==='past')$sql.=' AND e.event_date<CURDATE()';$sql.=' ORDER BY e.event_date DESC';$s=$pdo->prepare($sql);$s->execute($params);$regs=$s->fetchAll();$pageTitle='My events';require __DIR__.'/includes/header.php'; ?><section class="section section-soft"><div class="container"><span class="eyebrow">Your event history</span><h1 class="mt-3">My events & tickets</h1><p class="muted">Reopen your tickets whenever you need them.</p><form class="panel row g-3 mt-3 mb-4" method="get" data-validate novalidate data-no-lock><div class="col-md-7"><label class="form-label">Search</label><input class="form-control" name="q" maxlength="80" value="<?=e($q)?>" placeholder="Event title or registration ID"></div><div class="col-md-3"><label class="form-label">When</label><select class="form-select" name="status"><option value="all">All events</option><option value="upcoming" <?=$filter==='upcoming'?'selected':''?>>Upcoming</option><option value="past" <?=$filter==='past'?'selected':''?>>Past</option></select></div><div class="col-md-2 d-grid align-self-end"><button class="btn btn-primary">Filter</button></div></form><div class="panel"><?php if(!$regs): ?><div class="empty-state"><i class="bi bi-ticket-perforated fs-1"></i><h2 class="h5 mt-3">No tickets found</h2><p>Register for an event and your ticket will appear here.</p><a href="events.php" class="btn btn-primary">Explore events</a></div><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Event</th><th>Date & venue</th><th>Registration</th><th>Attendance</th><th></th></tr></thead><tbody><?php foreach($regs as $r): ?><tr><td><strong><?=e($r['title'])?></strong><div class="small muted text-capitalize"><?=e($r['event_status'])?></div></td><td><?=e(date('M j, Y',strtotime($r['event_date'])))?><div class="small muted"><?=e($r['venue'])?></div></td><td><span class="small"><?=e($r['registration_code'])?></span></td><td><span class="status-pill <?=$r['checked_in_at']?'status-checked':'status-pending'?>"><?=$r['checked_in_at']?'Checked in':'Not checked in'?></span></td><td><a class="btn btn-sm btn-outline-primary" href="ticket.php?id=<?=(int)$r['id']?>">View ticket</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div></section><?php require __DIR__.'/includes/footer.php'; ?>
